import requests
import pandas as pd


def task_func(url: str) -> pd.DataFrame:
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        data = response.json()
        return pd.DataFrame(data)
    except requests.RequestException as e:
        raise SystemError(f"Network error while fetching data from {url}: {e}") from e
    except ValueError as e:
        raise ValueError(f"Invalid JSON data or unsupported structure from {url}: {e}") from e
